contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        // feeRate must be <= 5000 for initialize to succeed
        require(feeRate <= 5000);

        // Drive the contract through its public initialize entry point
        c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        );

        // The rule: the nft getter must return the address supplied at initialization
        assert(c.nft() == nft);
    }

    receive() external payable {}
}
